CREATE TABLE IF NOT EXISTS pet_care_knowledge (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  knowledge_key CHAR(64) NOT NULL COMMENT 'stable row identity: activity + scope + source batch',
  species VARCHAR(32) NOT NULL,
  breed VARCHAR(100) NOT NULL DEFAULT 'unknown',
  life_stage VARCHAR(32) NOT NULL DEFAULT 'unknown',
  need_code VARCHAR(100) NOT NULL,
  care_activity_code VARCHAR(100) NOT NULL,
  care_activity_name VARCHAR(150) NOT NULL,
  care_subtype VARCHAR(64) NOT NULL DEFAULT 'unknown' COMMENT 'internal/external/both/all/unknown; NOT administration route',
  care_domain VARCHAR(64) DEFAULT NULL,
  care_category VARCHAR(100) DEFAULT NULL,
  care_type VARCHAR(32) DEFAULT NULL,
  applicable_conditions JSON DEFAULT NULL,
  schedule JSON DEFAULT NULL,
  tools_materials JSON DEFAULT NULL,
  methods JSON DEFAULT NULL,
  avoidances JSON DEFAULT NULL,
  observations JSON DEFAULT NULL,
  adjustment_rules JSON DEFAULT NULL,
  source_question TEXT,
  source_ids JSON DEFAULT NULL,
  evidence_status VARCHAR(32) NOT NULL DEFAULT 'pending_review',
  review_status VARCHAR(32) NOT NULL DEFAULT 'pending_review',
  source_batch VARCHAR(100) NOT NULL DEFAULT 'default',
  extraction_mode VARCHAR(24) NOT NULL DEFAULT 'conservative',
  extraction_notes JSON DEFAULT NULL,
  source_scope JSON DEFAULT NULL,
  original_payload JSON NOT NULL COMMENT 'Original activity, for provenance/audit',
  version INT NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_knowledge_key (knowledge_key),
  KEY idx_care_match (species, breed, life_stage, need_code, care_activity_code, care_subtype),
  KEY idx_review_status (review_status),
  KEY idx_batch (source_batch)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='宠析日常养护宽表';
